<script setup lang="ts">
import {ref,computed,watch,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {Download,RefreshCw,X,CheckCircle2,LoaderCircle} from 'lucide-vue-next'
import {api,query,downloadFile} from './api'
import UiSelect from './UiSelect.vue'
import MultiFilter from './MultiFilter.vue'
import SubmissionState from './SubmissionState.vue'
import FileUpload from './FileUpload.vue'
import WorkbenchPreview from './WorkbenchPreview.vue'
import WorkbenchStudents from './WorkbenchStudents.vue'
import BatchSources from './BatchSources.vue'
import BatchRosterDialog from './BatchRosterDialog.vue'
import ComparisonPanel from './ComparisonPanel.vue'
import PageTable from './PageTable.vue'
import SimpleTableHeader from './SimpleTableHeader.vue'
import ModuleWorkbenchAnalysis from './ModuleWorkbenchAnalysis.vue'
import WeeklyAnalysis from './WeeklyAnalysis.vue'
import {workbenchModules,workbenchPeriod} from './workbenchModules'
import {defaultTeachingPeriod,yearOptions,teachingPeriodRule} from './teachingCalendar'
import {classLabel} from './classPresentation'
import {usePaginationScroll} from './usePaginationScroll'
type Item=Record<string,any>
const props=withDefaults(defineProps<{kind?:string,user:Item,meta:Item}>(),{kind:'habit'}),emit=defineEmits<{navigate:[id:string]}>()
const initial=defaultTeachingPeriod(props.kind)
const config=computed(()=>workbenchModules[props.kind]),spec=computed(()=>props.meta.kinds[props.kind]),monthly=computed(()=>props.kind==='monthly')
const termOptions=computed(()=>props.meta.roster_options.terms.filter((t:Item)=>props.kind!=='scores'||t.value!=='夏'))
const rosterInitial=defaultTeachingPeriod('habit',props.kind==='monthly'?new Date(initial.year,initial.period-1,15):new Date()),rosterYear=ref(rosterInitial.year),rosterTerm=ref(rosterInitial.term)
function periodName(p:number){return workbenchPeriod(props.kind,p,spec.value.period_labels)}
const periodTitle=computed(()=>periodName(period.value)),contextTitle=computed(()=>monthly.value?`${year.value}年 · 名单 ${rosterYear.value}年${rosterTerm.value}季`:`${year.value}年${term.value}季`)
const year=ref(initial.year),term=ref(initial.term),period=ref(initial.period),teacher=ref(String(props.user.role==='teacher'?props.user.id:props.meta.teachers[0]?.id||''))
const upperData=ref<Item|null>(null),upperLoading=ref(false),upperError=ref('')
const queryTeacher=ref('')
const data=ref<Item|null>(null),history=ref<Item[]>([]),historyLoading=ref(false),historyError=ref(''),loading=ref(false),error=ref(''),actionError=ref(''),busy=ref(false)
const teacherRows=ref<Item[]>([]),teacherLoading=ref(false),teacherError=ref('')
const pageSize=30
const periodRule=computed(()=>teachingPeriodRule(props.meta,props.kind,term.value))
const submissionRequired=computed(()=>periodRule.value.required&&period.value<=periodRule.value.periods)
const historyColumns=['教师','提交文件','时间','实际数据','状态','操作'],teacherColumns=['教师','已交 / 应交班级','已填 / 应填学生','未填学生','提交情况','最近提交','查看']
const tab=ref('students'),times=ref<string[]>([]),grades=ref<string[]>([]),cohort=ref(''),status=ref(''),metric=ref('completion_level'),rank=ref(''),search=ref(''),classId=ref(''),sort=ref('schedule'),direction=ref<'asc'|'desc'>('asc'),page=ref(1)
const locatedClass=ref<Item|null>(null)
let drilling=false
const detail=ref<HTMLElement>(),queryTabs=ref<HTMLElement>(),queryNavHeight=ref(0),navTop=ref(65),queryFloor=ref(0),previewDialog=ref<HTMLDialogElement>(),preview=ref<Item|null>(null),file=ref<File|null>(null),replace=ref(false),ack=ref(false),mapping=ref<Record<string,string>>({}),historyRoster=ref<Item|null>(null),success=ref('')
let queryLayoutObserver:ResizeObserver|undefined
let detailScrollTimer:ReturnType<typeof setTimeout>|undefined,aligningDetail=false
function holdQuerySpace(){if(detail.value)queryFloor.value=Math.max(0,innerHeight-detail.value.getBoundingClientRect().top)}
function finishDetailScroll(){if(aligningDetail){aligningDetail=false;queryFloor.value=0;clearTimeout(detailScrollTimer)}}
function scrollDetail(){
 const anchor=detail.value
 if(!anchor)return
 // Scroll only the page; scrollIntoView also moves the wide table/tab scrollers.
 // Keep the workspace floor until the animation finishes when a panel shrinks.
 aligningDetail=true;clearTimeout(detailScrollTimer)
 window.scrollTo({top:Math.max(0,scrollY+anchor.getBoundingClientRect().top-navTop.value),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})
 detailScrollTimer=setTimeout(finishDetailScroll,1200)
}
async function selectTab(value:string){holdQuerySpace();tab.value=value;await nextTick();scrollDetail()}
const own=computed(()=>props.user.role==='manager'||props.user.role==='teacher'&&teacher.value===String(props.user.id))
const overview=computed(()=>upperData.value?.overview),fields=computed(()=>{const source=data.value?.fields||spec.value.fields;const order=props.kind==='habit'?['completion','days','reading_score']:[];return [...order.map(key=>source.find((f:Item)=>f[0]===key)).filter(Boolean),...source.filter((f:Item)=>!order.includes(f[0]))]}),selectedTeacher=computed(()=>props.meta.teachers.find((t:Item)=>String(t.id)===teacher.value)?.name||'请选择教师')
const periodOptions=computed(()=>(upperData.value?.context?.term===(monthly.value?'全年':term.value)?upperData.value.periods:Array.from({length:periodRule.value.required?periodRule.value.periods:0},(_,i)=>({period:i+1,state:'none'}))).map((p:Item)=>({value:p.period,label:`${periodName(p.period)} · ${p.state==='not_required'?'历史记录':p.state==='complete'?'✓ 已完成':p.state==='partial'?'● 待补全':p.state==='unknown'?'● 待核对':'○ 未提交'}`,state:p.state})))
const timeOptions=computed<string[]>(()=>data.value?.options.times||[])
const gradeOptions=computed<string[]>(()=>data.value?.options.grades||[])
const maxPage=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/pageSize)))
const sortFields=computed(()=>fields.value.map((f:Item)=>({key:f[0],type:f[2]})))
function scope(){return {kind:props.kind,year:year.value,term:monthly.value?'全年':term.value,period:period.value,teacher_id:teacher.value,...(monthly.value?{roster_year:rosterYear.value,roster_term:rosterTerm.value}:{})}}
function queryScope(){return {...scope(),teacher_id:queryTeacher.value}}
const queryTeacherName=computed(()=>props.meta.teachers.find((t:Item)=>String(t.id)===queryTeacher.value)?.name||'全部授权教师')
const rankLabel=computed(()=>({completion_level:'完成度',wechat_rate:'微信打卡',average_level:'两项平均',reading_level:'朗读分'} as Item)[metric.value]+(rank.value==='blank'?'未填':rank.value))
function params(){return {...queryScope(),times:times.value.join(','),grades:grades.value.join(','),cohort:cohort.value,status:status.value,search:search.value,metric:metric.value,rank:rank.value,class_id:classId.value,sort:sort.value,direction:direction.value,page:page.value,page_size:pageSize}}
const studentPagination=usePaginationScroll(()=>detail.value?.querySelector<HTMLElement>('.workbench-students'))
let pendingStudentPage:{ticket:ReturnType<typeof studentPagination.prepare>,key:string}|undefined
function cancelStudentPage(){pendingStudentPage=undefined;studentPagination.cancel()}
function turnStudents(next:number){if(loading.value||next<1||next>maxPage.value)return;cancelStudentPage();const ticket=studentPagination.prepare();pendingStudentPage={ticket,key:JSON.stringify({...params(),page:next})};page.value=next}
let version=0,timer:ReturnType<typeof setTimeout>|undefined
let historyVersion=0,historyLoadedKey='',historyPendingKey='',historyPending:Promise<void>|null=null
function scopeKey(){return JSON.stringify(queryScope())}
function refreshHistory(force=false):Promise<void>{
 const key=scopeKey()
 if(force){++historyVersion;historyLoadedKey='';historyPending=null;historyPendingKey=''}
 if(historyPending&&historyPendingKey===key)return historyPending
 if(!force&&historyLoadedKey===key)return Promise.resolve()
 const current=++historyVersion;historyLoading.value=true;historyError.value='';history.value=[];historyPendingKey=key
 const task=api(`teaching/history/?${query(queryScope())}`).then(result=>{
  if(current===historyVersion&&key===scopeKey()){holdQuerySpace();history.value=result.items;historyLoadedKey=key}
 }).catch(e=>{if(current===historyVersion&&key===scopeKey())historyError.value=(e as Error).message}).finally(()=>{
  if(current===historyVersion)historyLoading.value=false
  if(historyPending===task){historyPending=null;historyPendingKey=''}
 })
 historyPending=task
 return task
}
function queue(context=false,delay=0){if(pendingStudentPage&&pendingStudentPage.key!==JSON.stringify(params()))cancelStudentPage();clearTimeout(timer);++version;loading.value=true;timer=setTimeout(()=>void load(context),delay)}
async function load(context=false){
 const current=++version,intent=pendingStudentPage,key=JSON.stringify(params());loading.value=true;error.value='';void refreshHistory(context)
 try{const result=await api(`teaching/workbench/query/?${query(params())}`);if(current!==version)return;if(!intent)holdQuerySpace();data.value=result;await nextTick();if(intent&&pendingStudentPage===intent&&tab.value==='students'){finishDetailScroll();queryFloor.value=0;void studentPagination.finish(intent.ticket,()=>current===version&&tab.value==='students'&&JSON.stringify(params())===key).then(()=>{if(pendingStudentPage===intent)pendingStudentPage=undefined})}}
 catch(e){if(current===version){error.value=(e as Error).message;if(intent&&pendingStudentPage===intent)cancelStudentPage()}}
 finally{if(current===version)loading.value=false}
}
let upperVersion=0,statsVersion=0,statsLoadedKey=''
async function loadUpper(){const current=++upperVersion;upperLoading.value=true;upperError.value='';try{const result=await api(`teaching/workbench/overview/?${query(scope())}`);if(current===upperVersion)upperData.value=result}catch(e){if(current===upperVersion)upperError.value=(e as Error).message}finally{if(current===upperVersion)upperLoading.value=false}}
function clear(resetTeacher=true){if(resetTeacher)queryTeacher.value='';times.value=[];grades.value=[];cohort.value='';status.value='';search.value='';rank.value='';metric.value='completion_level';classId.value='';locatedClass.value=null;page.value=1}
function invalidateHistory(){++historyVersion;history.value=[];historyLoadedKey='';historyPending=null;historyPendingKey='';void refreshHistory()}
watch(teacher,()=>{preview.value=null;file.value=null;success.value='';void loadUpper()})
watch(term,()=>{if(props.kind==='habit'&&period.value>periodRule.value.periods)period.value=1})
watch([year,period],()=>{if(monthly.value){const value=defaultTeachingPeriod('habit',new Date(year.value,period.value-1,15));rosterYear.value=value.year;rosterTerm.value=value.term}})
watch([year,term,period,rosterYear,rosterTerm],()=>{clear(false);preview.value=null;file.value=null;success.value='';invalidateHistory();void loadUpper();statsLoadedKey='';++statsVersion;teacherRows.value=[];if(tab.value==='teachers')void loadStats();queue()})
watch(queryTeacher,()=>{if(!drilling)clear(false);invalidateHistory();queue()})
watch([times,grades,cohort,status,rank,metric,classId],()=>{if(classId.value&&locatedClass.value&&(times.value.length!==1||times.value[0]!==locatedClass.value.schedule)){classId.value='';locatedClass.value=null}page.value=1;queue()})
watch(search,()=>{page.value=1;queue(false,250)})
watch([sort,direction,page],()=>queue())
async function locate(cls?:Item,problem=false){drilling=true;clear();queryTeacher.value=teacher.value;if(cls){classId.value=String(cls.id);locatedClass.value=cls;times.value=[cls.schedule]}status.value=problem?'unfilled':'';tab.value='students';queue();await nextTick();drilling=false;scrollDetail()}
async function distribution(key:string,bucket:string){clear(false);metric.value=key;rank.value=bucket;tab.value='students';queue();await nextTick();scrollDetail()}
function sortBy(key:string){const type=sortFields.value.find((f:Item)=>f.key===key)?.type;const first=type==='number'||type==='percent'?'desc':'asc';if(sort.value!==key){sort.value=key;direction.value=first}else if(direction.value===first)direction.value=first==='asc'?'desc':'asc';else{sort.value='schedule';direction.value='asc'}page.value=1}
async function download(path:string){actionError.value='';try{await downloadFile(path)}catch(e){actionError.value=(e as Error).message}}
async function choose(selected:File){if(!own.value||busy.value||!submissionRequired.value)return;file.value=selected;replace.value=false;ack.value=false;preview.value=null;actionError.value='';busy.value=true;await nextTick();previewDialog.value?.showModal();try{const form=new FormData();form.append('file',selected);Object.entries(scope()).forEach(([k,v])=>form.append(k,String(v)));preview.value=await api('teaching/preview/',{method:'POST',body:form})}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function recheck(){if(!preview.value)return;busy.value=true;actionError.value='';try{preview.value=await api(`teaching/batches/${preview.value.id}/recheck/`,{method:'POST',body:JSON.stringify({class_mapping:mapping.value})})}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function commit(){if(!preview.value)return;actionError.value='';if(preview.value.existing&&!replace.value){actionError.value='请先勾选确认整份替换本期提交。';return}busy.value=true;try{await api(`teaching/batches/${preview.value.id}/commit/`,{method:'POST',body:JSON.stringify({replace:replace.value,roster_acknowledged:ack.value})});success.value='上次成功提交：刚刚';previewDialog.value?.close();preview.value=null;file.value=null;await Promise.all([loadUpper(),load(true),loadStats(true)])}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
function date(value:string){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
function value(v:any,type=''){return v===null||v===undefined||v===''?'—':type==='percent'?`${v}%`:v}
function statsScope(){return {...scope(),teacher_id:''}}
async function loadStats(force=false){const key=JSON.stringify(statsScope());if(!force&&statsLoadedKey===key)return;const current=++statsVersion;teacherLoading.value=true;teacherError.value='';try{const result=await api(`teaching/workbench/teachers/?${query(statsScope())}`);if(current===statsVersion&&key===JSON.stringify(statsScope())){holdQuerySpace();teacherRows.value=result.items;statsLoadedKey=key}}catch(e){if(current===statsVersion)teacherError.value=(e as Error).message}finally{if(current===statsVersion)teacherLoading.value=false}}
async function openTeachers(){await selectTab('teachers')}
async function viewTeacher(id:number){clear();queryTeacher.value=String(id);queue();await selectTab('students')}
async function refreshAll(){await Promise.all([loadUpper(),load(true),loadStats(true)])}
watch(tab,value=>{if(value!=='students')cancelStudentPage();if(value==='teachers')void loadStats()})
onMounted(()=>{window.addEventListener('scrollend',finishDetailScroll);void refreshAll();const topbar=document.querySelector<HTMLElement>('.topbar');const measure=()=>{navTop.value=topbar?.getBoundingClientRect().height||0;queryNavHeight.value=queryTabs.value?.getBoundingClientRect().height||0};queryLayoutObserver=new ResizeObserver(measure);if(topbar)queryLayoutObserver.observe(topbar);if(queryTabs.value)queryLayoutObserver.observe(queryTabs.value);measure()});onBeforeUnmount(()=>{++version;++historyVersion;++upperVersion;++statsVersion;clearTimeout(timer);queryLayoutObserver?.disconnect();clearTimeout(detailScrollTimer);window.removeEventListener('scrollend',finishDetailScroll)})
</script>
<template>
<div class="habit-workbench" :data-kind="kind" :data-period="data?.context?.period" :data-upper-teacher="upperData?.context?.teacher_id" :data-query-teacher="data?.context?.teacher_id||'all'">
 <div class="wb-context"><label>年份<UiSelect v-model="year" aria-label="年份" :options="yearOptions.map(v=>({value:v,label:v+' 年'}))"/></label><label v-if="!monthly">学期<UiSelect v-model="term" aria-label="学期" :options="termOptions"/></label><label v-if="monthly">班级年份<UiSelect v-model="rosterYear" aria-label="名单年份" :options="yearOptions.map(v=>({value:v,label:v+' 年'}))"/></label><label v-if="monthly">班级学期<UiSelect v-model="rosterTerm" aria-label="名单学期" :options="meta.roster_options.terms"/></label><label>提交教师<UiSelect v-model="teacher" aria-label="提交教师" :options="meta.teachers.map((t:Item)=>({value:String(t.id),label:t.name}))"/></label><label v-if="periodOptions.length" class="wb-week">{{config.periodField}}<UiSelect v-model="period" :aria-label="config.periodField" :options="periodOptions"><template #value="{option}"><span class="week-value">{{periodTitle}} <SubmissionState :state="option?.state||'none'"/></span></template><template #option="{option}"><span class="week-value">{{periodName(Number(option.value))}} <SubmissionState :state="option.state||'none'"/></span></template></UiSelect></label><button class="icon-button" aria-label="刷新工作台" :disabled="loading||upperLoading" @click="refreshAll"><RefreshCw :size="18"/></button><button class="text-button wb-teachers" @click="openTeachers">教师提交统计</button></div>
 <p v-if="upperError" role="alert" class="validation-summary">{{upperError}}</p>
 <div v-if="!upperData&&upperLoading" class="loading-inline"><LoaderCircle class="spin" :size="18"/>正在读取本期名单…</div>
 <p v-if="upperData&&overview?.classes.some((c:Item)=>c.basis!=='submission')" class="wb-scope-note">{{overview.notice}}</p>
 <p v-if="!submissionRequired" class="wb-no-task" role="status">{{kind==='scores'?'暑期无需填报课内成绩。可切换春季或秋季，下方保留历史查询。':'当前为历史周记录，仅供查询；暑期周习惯填报范围为第1—5周。'}}</p>
 <div class="wb-workarea" v-if="upperData&&submissionRequired">
  <section class="panel wb-overview" aria-label="本期各班提交情况" :aria-busy="upperLoading"><header><h2>{{selectedTeacher}} 的各班情况</h2><button class="text-button" @click="locate(undefined,!!overview?.review_count)">{{overview?.review_count?'查看未填学生 · '+overview.review_count+' 人':'查看全部学生'}}</button></header><div class="wb-overview-meta"><span><strong>{{overview?.class_count}}</strong> 个班</span><span><strong>{{overview?.student_count}}</strong> 名学生</span><span>已填 <strong>{{overview?.filled_count}} / {{overview?.student_count}}</strong> 人</span><span v-if="overview?.outside_count">另有 {{overview.outside_count}} 名名单外学生记录</span></div>
   <template v-if="overview?.classes.length"><div class="wb-classhead"><span>时间段 / 班级</span><span>人数</span><span>已填</span><span>提交情况</span></div><div class="wb-classrow" v-for="c in overview?.classes" :key="c.id" :data-class-id="c.id"><div class="wb-classname"><button class="text-button" @click="locate(c)">{{c.schedule}}</button><span>{{c.grade}} · {{c.is_experimental?'实验班':c.is_experimental===false?'普通班':'旧记录未关联'}}</span></div><button class="text-button" :aria-label="'查看'+c.schedule+'全部'+c.student_count+'名学生'" @click="locate(c)">{{c.student_count}}</button><span>{{c.filled_count}} / {{c.student_count}}</span><button class="wb-class-state" @click="locate(c,c.review_count>0)"><SubmissionState :state="c.state"/><span v-if="c.review_count&&c.submitted" class="wb-review-count">{{c.review_count}} 人</span></button></div></template>
   <div v-else class="empty-state compact">{{own?'尚未建立本期班级／学生名单。':'当前没有已提交的数据，未提交名单按权限保护。'}}<button v-if="own" class="text-button" @click="emit('navigate','roster')">维护班级与学生</button></div>
  </section>
  <aside class="panel wb-upload" aria-label="新建上传"><h2>新建上传</h2><div class="wb-upload-scope"><strong>{{selectedTeacher}} · {{periodTitle}}</strong><span>{{contextTitle}} · {{overview?.class_count}} 个班 · {{overview?.student_count}} 名学生</span></div><FileUpload :disabled="!own||upperLoading||!overview?.student_count" :busy="busy" :filename="file?.name" :title="'新建'+config.uploadName+'上传'" button-text="选择文件并预览" @select="choose" @invalid="actionError=$event"/><button class="text-button" :disabled="!own||upperLoading||!overview?.student_count||busy" @click="download(`teaching/template/?${query(scope())}`)"><Download :size="15"/>下载已填名单的模板</button><p class="wb-subtle">{{config.inputHelp}}</p><div class="wb-upload-foot"><p v-if="success" class="wb-success"><CheckCircle2 :size="16"/>{{success}}</p><template v-else-if="overview?.has_submission">上次提交：{{date(overview.last_submitted_at)}}<br/>再次提交将整份替换本期数据。</template><template v-else>本期尚未提交。名单已准备好后，可下载模板填写。</template></div><p v-if="actionError&&!previewDialog?.open" class="field-error" role="alert">{{actionError}}</p></aside>
 </div>
 <div ref="detail" class="wb-detail-anchor wb-query-workspace" :style="{'--wb-nav-top':navTop+'px','--wb-tabs-height':queryNavHeight+'px','--wb-view-floor':queryFloor+'px'}"><div ref="queryTabs" class="wb-tabs" role="tablist" aria-label="教学数据查询"><button v-for="t in [{id:'students',label:'学生明细'},{id:'history',label:'提交历史'},{id:'analysis',label:'分析汇总'},{id:'teachers',label:'教师提交统计'},...(kind==='scores'?[{id:'comparison',label:'跨期比较'}]:[])]" :key="t.id" role="tab" :aria-selected="tab===t.id" @click="selectTab(t.id)">{{t.label}}</button></div>
 <section v-if="tab==='students'&&data" class="panel wb-detail" role="tabpanel" aria-label="学生明细" :aria-busy="loading">
  <header><h2>学生明细</h2><div><button class="text-button" @click="clear();queue()">清除筛选</button><button class="btn small" :disabled="loading" @click="download(`teaching/workbench/query/export/?${query(params())}`)"><Download :size="15"/>下载筛选结果</button></div></header>
  <div class="wb-filters">
   <label>查询教师<UiSelect wide v-model="queryTeacher" aria-label="查询教师" :options="[{value:'',label:'全部教师'},...meta.teachers.map((t:Item)=>({value:String(t.id),label:t.name}))]"/></label>
   <label>时间段<MultiFilter v-model="times" :options="timeOptions" label="时间段"/></label>
   <label>年级<MultiFilter v-model="grades" :options="gradeOptions" label="年级"/></label>
   <label>班型<UiSelect v-model="cohort" aria-label="班型" :options="[{value:'',label:'全部班型'},{value:'regular',label:'普通班'},{value:'experimental',label:'实验班'}]"/></label>
   <label>填写情况<UiSelect v-model="status" aria-label="填写情况" :options="[{value:'',label:'全部'},{value:'filled',label:'已填'},{value:'unfilled',label:'未填'}]"/></label>
   <label>学生姓名<input v-model="search" aria-label="学生姓名" type="search" placeholder="姓名或英文名"/></label>
  </div>
  <div v-if="rank||classId" class="wb-condition-tags"><span v-if="rank" class="wb-condition-tag">{{rankLabel}}<button aria-label="清除等级条件" @click="rank=''">×</button></span><span v-if="classId" class="wb-condition-tag">{{queryTeacherName}} · {{classLabel(locatedClass||{})}}<button aria-label="清除班级定位" @click="classId='';locatedClass=null;times=[]">×</button></span></div>
  <p v-if="error" role="alert" class="validation-summary wb-query-error">{{error}}</p>
  <div class="wb-result"><span>{{queryTeacherName}} · 查询范围 {{data.scope.student_count}} 人 · 当前匹配 {{data.total}} 人</span></div>
  <WorkbenchStudents :kind="kind" :sticky-offset="queryNavHeight" :items="data.items" :fields="fields" :sort="sort" :direction="direction" @sort="sortBy"/>
  <p v-if="!data.total" class="empty-state compact">没有符合条件的学生，可清除筛选返回全部授权教师。</p>
  <footer class="wb-pager"><span>{{(page-1)*pageSize+(data.total?1:0)}}–{{Math.min(page*pageSize,data.total)}} / {{data.total}} 人</span><div><button class="btn small" :disabled="loading||page<=1" @click="turnStudents(page-1)">上一页</button><span>{{page}} / {{maxPage}}</span><button class="btn small" :disabled="loading||page>=maxPage" @click="turnStudents(page+1)">下一页</button></div></footer>
  <div class="wb-detail-tools"><details v-if="data.scope.notice" class="wb-query-help"><summary>查询说明</summary><p>{{data.scope.notice}}</p></details><BatchSources label="原件信息" :records="data.items.flatMap((s:Item)=>s.records)" :user="user"/></div>
 </section>
 <section v-if="tab==='history'" class="panel wb-history" role="tabpanel" aria-label="提交历史"><header><h2>提交历史</h2><span>{{queryTeacherName}} · {{periodTitle}}</span></header><details class="wb-panel-help"><summary>查询说明</summary><p>{{user.role==='teacher'?'历史与原件仅显示本人获准访问的提交；其他教师可读数据见学生明细。':'显示查询教师范围内获准访问的提交历史。'}}</p></details><PageTable label="提交历史" :has-rows="history.length>0"><table><SimpleTableHeader :columns="historyColumns"/><tbody><tr v-for="b in history" :key="b.id" :data-batch-id="b.id"><td>{{meta.teachers.find((t:Item)=>String(t.id)===String(b.teacher_id))?.name||b.teacher}}</td><td>{{b.filename}}</td><td>{{date(b.created_at)}}</td><td>{{b.count}} 条</td><td>{{b.status==='active'?'当前有效':b.status==='superseded'?'已替换':'已撤回'}}</td><td><button class="text-button" @click="download(`teaching/batches/${b.id}/`)">下载原件</button><button class="text-button" @click="historyRoster=b">查看当时内容与名单</button></td></tr></tbody></table><template #header><SimpleTableHeader :columns="historyColumns"/></template></PageTable><p v-if="historyLoading" class="loading-inline wb-history-loading">正在读取提交历史…</p><p v-if="historyError" class="field-error" role="alert">{{historyError}}</p><p v-if="!historyLoading&&!historyError&&!history.length" class="empty-state compact">暂无此查询范围内可查看的提交历史。</p></section>
 <section v-if="tab==='analysis'&&kind==='habit'" class="panel wb-analysis" role="tabpanel" aria-label="分析汇总"><WeeklyAnalysis :year="year" :term="term" :period="period" :teacher="queryTeacher" :user="user" :meta="meta" @layout="holdQuerySpace"/></section>
 <section v-if="tab==='analysis'&&data&&kind!=='habit'" class="panel wb-analysis" role="tabpanel" aria-label="分析汇总"><header><div><h2>{{periodTitle}}分析</h2><p>{{queryTeacherName}} · {{contextTitle}}</p></div></header><ModuleWorkbenchAnalysis :kind="kind" :summary="data.analysis.legacy" :scope="queryScope()" :user="user" :meta="meta" @download="download" @rank="distribution"/></section>
