 <dialog ref="previewDialog" class="wb-preview-dialog" aria-label="上传预览" @cancel="busy&&$event.preventDefault()"><header><div><h2>上传预览</h2><p>{{selectedTeacher}} · {{contextTitle}} · {{periodTitle}}</p></div><button class="icon-button" aria-label="关闭上传预览" :disabled="busy" @click="previewDialog?.close()"><X :size="20"/></button></header><div class="wb-preview-body"><p v-if="busy&&!preview" class="loading-inline">正在解析文件…</p><template v-if="preview"><p class="wb-preview-state">{{preview.errors.length?'请补齐或修正下列问题后重新上传':'校验通过，可以确认提交'}} · {{preview.count}} 条实际指标记录</p><WorkbenchPreview :kind="kind" v-if="preview.roster_check?.classes" v-model="mapping" :check="preview.roster_check" :errors="preview.errors" @manage="previewDialog?.close();emit('navigate','roster')" @recheck="recheck"/><details v-if="preview.errors.length&&!preview.roster_check?.classes?.length" class="wb-diagnostics"><summary>文件问题（{{preview.errors.length}}）</summary><p v-for="(e,i) in preview.errors" :key="i">{{e.sheet}} {{e.row?'第'+e.row+'行':''}}：{{e.message}}</p></details><label v-if="preview.existing" class="wb-ack"><input v-model="replace" type="checkbox" :aria-label="kind==='habit'?'确认整份替换本周提交':'确认整份替换本期提交'"/>整份替换本期 {{preview.existing.filename}}，旧原件与内容保留在历史中。</label><label v-if="preview.roster_check?.requires_acknowledgement" class="wb-ack"><input v-model="ack" type="checkbox"/>已核对名单差异，确认本期提交范围</label></template></div><footer><p v-if="actionError" role="alert" class="field-error">{{actionError}}</p><button class="btn" :disabled="busy" @click="previewDialog?.close()">返回修改</button><button class="btn primary" :disabled="busy||!preview||!!preview.errors.length" @click="commit">确认提交</button></footer></dialog>
 <section v-if="tab==='teachers'" class="panel wb-statistics" role="tabpanel" aria-label="教师提交统计"><header><div><h2>教师提交统计</h2><p>{{contextTitle}} · {{periodTitle}} · 全部授权教师</p></div><button class="btn small" :disabled="teacherLoading" @click="loadStats(true)">刷新统计</button></header><p v-if="teacherLoading" class="loading-inline">正在读取统计…</p><p v-if="teacherError" role="alert" class="field-error">{{teacherError}}</p><PageTable label="教师提交统计" :has-rows="teacherRows.length>0"><table><SimpleTableHeader :columns="teacherColumns"/><tbody><tr v-for="t in teacherRows" :key="t.id" :data-summary-teacher="t.id"><td>{{t.teacher}}</td><td>{{t.submitted_class_count}} / {{t.class_count??'—'}}</td><td>{{t.filled_count}} / {{t.student_count??'—'}}<small v-if="t.outside_count">另 {{t.outside_count}} 条名单外记录</small></td><td>{{t.review_count??'—'}}</td><td><span v-if="t.roster_empty" class="wb-subtle">尚未建名单</span><SubmissionState v-else :state="t.state"/><small v-if="t.scope_note&&!t.roster_empty">{{t.scope_note}}</small></td><td>{{date(t.last_submitted_at)}}</td><td><button class="text-button" @click="viewTeacher(t.id)">查看明细</button></td></tr></tbody></table><template #header><SimpleTableHeader :columns="teacherColumns"/></template></PageTable><details class="wb-panel-help"><summary>统计说明</summary><p>其他教师的未提交名单和原件仍按权限保护；没有历史名单时，不推断缺漏。</p></details></section>
